import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick heuristic approach to meet time constraint and model size
    # Use top features based on t-statistics
    t_stats = []
    for i in range(len(feats.ids)):
        try:
            t_stat = abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic)
            t_stats.append(t_stat)
        except:
            t_stats.append(0)

    # Get indices of top features
    top_indices = np.argsort(t_stats)[::-1][:MAX_DRIVERS]

    # Remove near-duplicates based on correlation
    selected_ids = []
    for i in top_indices:
        fid = feats.ids[i]
        # Check if this feature is too similar to already selected ones
        is_duplicate = False
        for kept_fid in selected_ids:
            if abs(np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(kept_fid)])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected_ids.append(fid)
        if len(selected_ids) >= MAX_DRIVERS:
            break

    # Create design
    drivers = tuple(selected_ids)

    # Use all original features as columns
    columns = tuple(feats.ids)

    # No products
    products = ()

    # Simple loadings based on t-statistics
    loadings = {}
    for i, fid in enumerate(feats.ids):
        loadings[fid] = t_stats[i]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
